import{settlementBuildingChoices}from'./settlement-generator.js';import{buildingFloorCount}from'./building-floors.js';import{chooseRoom}from'./settlement-library.js';
export const REGION_FACILITIES=['centre','mart','gym','game-corner','department-store','cave'];
export function areaSettings(node,defaults){return{...defaults,...node.settings,features:{...defaults.features,...node.settings?.features}};}
export function fitRegionCapacity(project,plan,library,reader,profile,defaults,{autoFit=true}={}){
 const settings=new Map(plan.nodes.map(n=>[n.id,areaSettings(n,defaults)])),adjustments=[],maxMaps=80-project.maps.length,maxTiles=400000-project.maps.reduce((s,m)=>s+m.width*m.height,0);
 const estimate=()=>{let maps=plan.nodes.length,tiles=plan.nodes.reduce((s,n)=>s+n.width*n.height,0);for(const n of plan.nodes.filter(n=>n.kind==='settlement')){const o=settings.get(n.id);if(!o.interiors)continue;const{buildings}=settlementBuildingChoices(library,project,reader,profile,{...o,seed:n.seed,preset:n.biome+'-'+plan.settlementSize});for(const t of buildings){if(t.kind==='department-store'){const family=library.departmentStores.find(f=>f.id===t.departmentFamily)||library.departmentStores[0];maps+=family.floors.length;tiles+=family.floors.reduce((s,f)=>s+f.width*f.height,0);}else{const room=chooseRoom(library,t);if(room&&t.entrances?.length){const count=buildingFloorCount(t);maps+=count;tiles+=room.width*room.height*count;}}}}return{maps,tiles};};
 let needed=estimate();while(autoFit&&(needed.maps>maxMaps||needed.tiles>maxTiles)){const candidates=plan.nodes.filter(n=>n.kind==='settlement'&&settings.get(n.id).interiors&&settings.get(n.id).houseCount>0).sort((a,b)=>settings.get(b.id).houseCount-settings.get(a.id).houseCount||b.id-a.id);if(!candidates.length)break;const n=candidates[0],o=settings.get(n.id);o.houseCount--;needed=estimate();}
 for(const n of plan.nodes){const before=areaSettings(n,defaults),after=settings.get(n.id);if(before.houseCount!==after.houseCount)adjustments.push(n.name+': houses '+before.houseCount+' → '+after.houseCount+' to fit project capacity.');}
 if(needed.maps>maxMaps||needed.tiles>maxTiles){const error=Error('This region needs about '+needed.maps+' maps and '+needed.tiles.toLocaleString()+' tiles; this project has room for '+Math.max(0,maxMaps)+' maps and '+Math.max(0,maxTiles).toLocaleString()+' tiles. Reduce facilities, turn off interiors in selected areas, or start a new project. Nothing has been added.');error.code='REGION_CAPACITY';throw error;}return{settings,adjustments,estimate:needed,available:{maps:maxMaps,tiles:maxTiles}};
}
